from pathlib import Path

files = [Path('functions/parceiro/[slug].js'), Path('functions/parceiro-feed/[slug].js')]
css = r'''
/* PREMIUM COASTAL REFRESH — global partner pages */
:root{--brand:#123f4a;--accent:#c89358;--ink:#17313a;--muted:#65777a;--sand:#f6f3ee;--line:#e7e0d7;--white:#fffdf9;--soft:#e7efeb;--teal:#3d817b;--shadow:0 24px 60px rgba(28,55,59,.10)}
body{background:var(--sand);color:var(--ink);font-family:'DM Sans',sans-serif;letter-spacing:-.01em}
body:before{content:'';position:fixed;inset:0;pointer-events:none;opacity:.24;background-image:radial-gradient(rgba(18,63,74,.12) .55px,transparent .55px);background-size:6px 6px;z-index:-1}
.site-header{background:linear-gradient(180deg,rgba(11,35,42,.58),rgba(11,35,42,.12))!important;border-bottom:1px solid rgba(255,255,255,.25);backdrop-filter:blur(10px)!important}
.nav{padding:16px 24px}.brand-name{font-family:Fraunces,serif;font-size:18px;color:#fff;text-shadow:0 2px 10px rgba(0,0,0,.24)}.brand-sub{color:rgba(255,255,255,.75);font-size:9px}
.site-header .nav-links{gap:8px}.site-header .nav-links>a{border-color:rgba(255,255,255,.4);background:rgba(11,35,42,.25);padding:9px 14px;font-size:12px;letter-spacing:.01em}.site-header .nav-links>.nav-cta{background:var(--accent);border-color:var(--accent);color:#fff;box-shadow:0 8px 24px rgba(0,0,0,.18)}
.hero{min-height:520px;background:var(--brand)}.hero:after{background:linear-gradient(90deg,rgba(8,35,43,.82) 0%,rgba(8,35,43,.48) 48%,rgba(8,35,43,.2) 100%),linear-gradient(0deg,rgba(8,35,43,.65),transparent 58%)}.hero-bg{opacity:.78;filter:saturate(.82) contrast(1.04)}.hero-inner{padding:118px 24px 70px}.eyebrow{color:#e5b878;font-size:10px;letter-spacing:.22em}.hero h1{font-family:Fraunces,serif;font-weight:500;font-size:clamp(46px,7vw,88px);letter-spacing:-.055em;max-width:850px;margin:17px 0 14px}.hero-title-clean span+span{font-size:.54em;color:#e5b878;letter-spacing:.01em;font-family:'DM Sans',sans-serif;font-weight:500}.hero p{max-width:580px;font-size:16px;color:rgba(255,255,255,.82)}.hero-actions{margin-top:28px}.hero-action{min-height:46px;padding:12px 20px;border-radius:10px}.hero-action.primary{background:var(--accent);color:#fff;box-shadow:0 12px 28px rgba(0,0,0,.2)}.hero-action.secondary{border-color:rgba(255,255,255,.5);background:rgba(255,255,255,.1)}.hero-quick{margin-top:24px}.hero-quick span{border-radius:8px;background:rgba(255,255,255,.09);padding:8px 11px}
.main{padding:42px 24px 120px}.search-panel{margin:-66px auto 32px;border:1px solid rgba(18,63,74,.08);border-radius:18px;padding:24px;box-shadow:var(--shadow);background:rgba(255,253,249,.96)}.search-head h2{font-family:Fraunces,serif;font-size:32px;font-weight:500}.search-form input,.search-form select{border-color:#dedbd4;background:#faf8f4;border-radius:9px}.search-form button{background:var(--brand);border-radius:9px;box-shadow:none}.category-chip{border-color:rgba(18,63,74,.1);border-radius:12px;background:rgba(255,253,249,.7);box-shadow:0 8px 20px rgba(28,55,59,.04)}.category-chip>span{background:#e5efeb}.feature-strip{border:0;border-radius:14px;background:linear-gradient(105deg,#e7efeb,#f2e8da)}
.property-section{padding:54px 0 42px}.property-section.section-tone-soft{margin-left:-28px;margin-right:-28px;padding:48px 28px;border:0;border-radius:22px;background:rgba(231,239,235,.54)}.section-head{margin-bottom:26px}.section-head h2,.sr-title{font-family:Fraunces,serif;font-weight:500;letter-spacing:-.045em}.section-head h2{font-size:clamp(34px,4.8vw,56px)}.section-head h2 small{color:var(--teal);font-size:11px;letter-spacing:.2em}.property-grid,.condos-grid{gap:18px}.property-card,.condo-card{border:1px solid rgba(18,63,74,.09);border-radius:14px;background:rgba(255,253,249,.96);box-shadow:0 12px 34px rgba(28,55,59,.065)}.property-card:hover,.condo-card:hover{box-shadow:0 20px 44px rgba(28,55,59,.12);border-color:rgba(200,147,88,.42)}.property-badge{background:var(--brand);color:#fff;border-radius:7px;padding:6px 9px}.property-body{padding:18px}.property-label{color:var(--teal);letter-spacing:.18em}.property-body h3,.condo-body h3{font-family:Fraunces,serif;font-weight:500}.property-body h3{font-size:21px}.property-body strong{color:var(--brand);font-size:18px}.property-link,.property-interest{border-radius:8px}.property-link{border-color:rgba(18,63,74,.2);color:var(--brand)}.property-interest{background:var(--teal)}.section-more-btn{border-color:rgba(18,63,74,.25);border-radius:9px;color:var(--brand);box-shadow:none}.section-more-btn:hover{background:var(--brand)}
.contact{margin-top:88px;border-radius:18px;background:linear-gradient(130deg,#123f4a,#1d5c62);box-shadow:0 24px 50px rgba(18,63,74,.17);padding:38px}.contact h2{font-family:Fraunces,serif;font-weight:500;font-size:44px}.form-submit{border-radius:8px;background:var(--accent);color:#fff}.profile-photo{border-radius:12px;border-color:rgba(229,184,120,.9)}footer{background:#102f39;border-top:4px solid var(--accent)}.footer-logo{font-family:Fraunces,serif;font-weight:500}
@media(max-width:800px){.nav{padding:12px 14px}.brand-name{font-size:16px}.site-header .nav-links>a{padding:8px 10px;font-size:10px}.hero{min-height:560px}.hero-inner{padding:112px 18px 48px}.hero h1{font-size:clamp(42px,13vw,66px)}.hero p{font-size:14px}.main{padding:30px 16px 104px}.search-panel{margin:-38px auto 24px;padding:18px;border-radius:15px}.search-head h2{font-size:28px}.property-section.section-tone-soft{margin-left:-16px;margin-right:-16px;padding-left:16px;padding-right:16px;border-radius:16px}.section-head h2{font-size:40px}.contact{padding:24px;border-radius:15px}.contact h2{font-size:36px}}
@media(prefers-reduced-motion:no-preference){.property-card,.condo-card,.hero-action,.section-more-btn{transition:transform .2s cubic-bezier(.23,1,.32,1),box-shadow .2s ease,border-color .2s ease}.property-card:hover,.condo-card:hover{transform:translateY(-5px)}}
'''

for path in files:
    text = path.read_text()
    if 'PREMIUM COASTAL REFRESH' in text:
        continue
    if '</style>' not in text:
        raise SystemExit(f'missing style close: {path}')
    path.write_text(text.replace('</style>', css + '\n</style>', 1))
    print(path)
